        commentary: "த்ருதராஷ்டிர மன்னர், பிறவியிலேயே பார்வையற்றவராக இருந்ததோடு, ஆன்மீக ஞானமும் இல்லாதவராக இருந்தார். தன் மகன்கள் மீது கொண்ட பற்றின் காரணத்தினால் அறவழியில் இருந்து விலகி பாண்டவர்களுக்கு உரிமையான ராஜ்யத்தை அவர்களிடமிருந்து அபகரித்தவர். தன்னை குற்றவாளியாக உணர்ந்த அவரது மனசாட்சி போரின் முடிவு குறித்து அவரைக் கவலையடையச் செய்தது. எனவே, குருக்ஷேத்திரத்தில் நடக்கவிருந்த போரின் நிகழ்வுகள் குறித்து ஸஞ்ஜயனிடம் விசாரித்தார்.\nஇந்த வசனத்தில் மன்னர் த்ருதராஷ்டிரர் ஸஞ்ஜயனிடம் போர்க்களத்தில் கூடியிருந்த தன் மகன்களும் தன் தம்பி பாண்டுவின் மகன்களும் என்ன செய்து கொண்டிருந்தார்கள் என்று கேட்டார். குருக்ஷேத்திரத்தின் போர்க்களத்தில் கூடியிருந்த இரு படைகளும் தவிர்க்க முடியாத ஒரு போரை எதிர்கொள்ள தயாராக இருந்தன. ஆயினும், அவர்கள் போராடுவார்கள் என்பது வெளிப்படையாக இருந்த போதிலும் அவர் ஏன் அத்தகைய கேள்வியைக் கேட்டார்?\nத்ருதரஷ்டிரர் பயன்படுத்திய தர்மக்ஷேத்ரே-- தர்ம பூமி (நல்லொழுக்கமுள்ள நடத்தை) என்ற சொற்கள் அவர் அனுபவிக்கும் சங்கடத்தை சித்தரிக்கின்றன. சடங்குகளை விவரிக்கும் யஜுர் வேத பாடநூல், ஶதபத் ப்ரஹ்மத்தில் குருக்ஷேத்திரம்—குருக்ஷேத்ரம் தேவ, யஜனம் என்று விவரிக்கப்பட்டுள்ளது. இதன் பொருள் ‘குருக்ஷேத்திரம் விண்ணுலக தேவர்களின் யாக அரங்கம்’ என்பதாகும். எனவே, இது தர்மத்தை வளர்த்த புனித பூமியாகக் கருதப்பட்டது. இந்த புனித பூமி தனது மகன்களில் பாகுபாட்டின் திறனைத் தூண்டும் என்று பயந்தார். மேலும், அவர்கள் தங்கள் உறவினர்களான பாண்டவர்களின் படுகொலையை முறையற்றதாகக் கருதி, அவர்களை அழிப்பதில் இருந்து விலகி பேச்சுவார்த்தை நடத்தக்கூடும். இப்படி அவர்கள் யோசித்தால், அவர்கள் அமைதியான தீர்வுக்கு ஒப்புக் கொள்ளலாம். இந்த சாத்தியக்கூறுகள் குறித்து அவர் மிகுந்த அதிருப்தியை உணர்ந்தார். ஒரு அமைதியான தீர்வு ஏற்பட்டால் பாண்டவர்கள் தொடர்ந்து தன் மகன்களுக்கு ஒரு தடையாக இருப்பார்கள் என்று கருதினார். எனவே, போர் நடப்பதை விரும்பினார். அதேசமயம் போரின் விளைவுகள் குறித்து அவர் நிச்சயமற்றவராக இருந்தார். மற்றும், அவரது மகன்களின் தலைவிதியை தீர்மானிக்க விரும்பினார். அதன் விளைவாக, இரு படைகளும் கூடியிருந்த குருக்ஷேத்திரப் போர்க்களத்தில் நடந்த நிகழ்வுகளைப் பற்றி ஸஞ்ஜயனிடம் கேட்டார்.",
