        commentary: "తన పుత్రులు ఎలాగైనా యుద్ధం మొదలు పెడతారనే ధ్రువీకరణ కోసం ధృతరాష్ట్రుడు ఎదురు చూస్తున్నాడు. ఈ ప్రశ్న వెనకున్న ధృతరాష్ట్రుని ఉద్దేశాన్ని అర్థం చేసుకున్న సంజయుడు, ఖచ్చితంగా యుద్ధం జరగబోతోందని, పాండవ సైన్యం యుద్ధానికి సిద్ధంగా సైనిక నిర్మాణంతో ఉందని చెప్పాడు. అంతేకాక దుర్యోధనుడు ఏమి చేస్తున్నాడనే దిశగా, సంభాషణ విషయాన్ని మరల్చాడు. \n       ధృతరాష్ట్రుని పెద్ద కొడుకు అయిన దుర్యోధనుడు చాల దుష్ట, క్రూర స్వభావం కలవాడు. ధృతరాష్ట్రుడు అంధుడు అవటం వలన, అతని తరఫున, నిజానికి దుర్యోధనుడే హస్తినాపుర రాజ్యాన్ని పరిపాలించాడు. అతను పాండవ ద్వేషి. ఎలాగైనా పాండవులని అడ్డు తొలగించుకొని రాజ్యాన్ని ఎదురు లేకుండా పాలించాలని నిశ్చయించుకున్నాడు. తన సైన్యాన్ని ఎదుర్కోగలిగినంత సైన్యాన్ని పాండవులు సమీకరించుకోలేరు, అని అనుకున్నాడు. కానీ దానికి విరుద్ధంగా జరిగింది, మరియు అపారమైన పాండవుల సైనిక సామర్ధ్యాన్ని చూచి వ్యాకులతతో ఆందోళన చెందాడు. \n       దుర్యోధనుడు తన యుద్ధ-గురువు ద్రోణాచార్యుని సమీపించటం, యుద్ధ పరిణామం మీద అతనికి వున్న భయాన్ని తెలియపరుస్తోంది. నమస్కరించాలనే నెపంతో ద్రోణాచార్యుని దగ్గరకి వెళ్ళినా, అతని నిజమైన ఆంతర్యం తన ఆందోళనని ఉపశమనం చేసుకోవటమే. ఈ ఇప్పుడు దుర్యోధనుడు తదుపరి శ్లోకంతో మొదలిడి తొమ్మిది శ్లోకాలని పలికెను.",
