        commentary: "துரியோதனன் தனது ஆசிரியருக்கு அவர் கடந்த காலத்தில் செய்த 'தவறை நுட்பமாக நினைவு படுத்தினான். பல ஆண்டுகளுக்கு முன்பு, பாண்டவர்களுடன் த்ரோணாச்சாரியர் ஒரு போரில் மன்னர் த்ருபதனை தோற்கடித்து, அவரது ராஜ்யத்தில் பாதியைக் கைப்பற்றியவர். தனது தோல்விக்கு பழிவாங்கும் நோக்கத்துடன் ஒரு மகனை பெறுவதற்காக த்ருபதன் ஒரு யாகத்தை செய்தார். இந்த யாக வேள்வியில் இருந்து எதிர்காலத்தில் த்ரோணாச்சாரியரை கொல்வதற்கான வரத்துடன் த்ருஷ்டத்யும்னன் பிறந்தான்.\nஇதை த்ரோணாச்சாரியர் முன்கூட்டியே அறிந்து இருந்தாலும் த்ருஷ்டத்யும்னன் இராணுவ பயிற்சிக்காக அவரை அணுகியபோது அவர் மிகவும் தாழ்மையுடன் ஏற்றுக்கொண்டு தனது அறிவை பாரபட்சமின்றி தனது மாணவருக்கு வழங்கியவர். இப்பொழுது, போரில், த்ருஷ்டத்யும்னன் பாண்டவர்களின் பக்கம் அவர்களின் இராணுவப்படைத் தளபதியாக இருந்தான். துரியோதனன் த்ரோணாச்சாரியரை பாண்டவ இராணுவத்தின் தளபதியான த்ருஷ்டத்யும்னனால் திறமையாக ஒழுங்கமைக்கப்பட்ட பாண்டவ இராணுவத்தை பார்க்கும்படி கூறினான். அவன் தன் ஆசிரியரிடம் கடந்த காலத்தில் அவரது கனிவான போக்கு அவர்களை இப்போதைய பிரச்சனையில் சிக்க வைத்துள்ளது என்றும் இனி பாண்டவர்களுடன் போரிடுவதில் மென்மை காட்டக்கூடாது என்றும் சுட்டிக்காட்டினான்.",
