        commentary: "రాబోయే పెను విపత్తు భయానికి, దుర్యోధనుడికి, పాండవులు సమీకరించిన సైన్యం, ఉన్న దాని కన్నా చాలా ఎక్కువగా అనిపిస్తోంది. తన ఆందోళనని వ్యక్తం చేస్తూ, పాండవుల పక్షంలోనున్న మహారథులను (పదివేల మంది సాధారణ యోధుల బలంతో సమానమైన బలం ఉన్న ఒక్కో యోధులు) చూపాడు. పాండవ పక్షంలో ఉన్న విశేషమైన నాయకులను దుర్యోధనుడు పేర్కొన్నాడు. వీరందరూ భీమార్జునులతో సమానమైన యోధులు మరియు యుద్ధంలో గట్టి పోటీ ఇచ్చేవారే.",
