        commentary: "दुर्योधन के आत्म प्रशंसा करने वाले ये शब्द मिथ्याभिमान करने वाले मनुष्यों की उक्ति जैसे थे। जब उन्हें अपना अन्त निकट दिखाई देता है तब स्थिति का आंकलन करने के पश्चात् आत्मप्रशंसा करने वाले व्यक्ति अभिमानपूर्वक मिथ्या गर्व करने लगते हैं। अपने भविष्य के प्रति अनर्थकारी व्यंग्योक्ति दुर्योधन के कथन में तब अभिव्यक्त हुई जब उसने कहा कि भीष्म पितामह द्वारा संरक्षित उनकी शक्ति असीमित थी।\nभीष्म पितामह कौरव सेना के प्रधान सेनापति थे। उन्हें इच्छा मृत्यु और अपनी मृत्यु का समय निश्चित करने का वरदान प्राप्त था जिससे वह अजेय कहलाते थे। पाण्डव पक्ष की सेना भीम के संरक्षण में थी जो दुर्योधन का जन्मजात शत्रु था। इसलिए दुर्योधन ने भीष्म के साथ भीम की अल्प शक्ति की तुलना की। भीष्म कौरव और पाण्डवों के पितामह थे और वे वस्तुतः दोनों पक्षों का कल्याण चाहते थे। पाण्डवों के प्रति करुणा भाव भीष्म पितामह को तन्मयता से युद्ध करने से रोकता था। वे यह भी जानते थे कि इस धर्मयुद्ध में भगवान श्रीकृष्ण पाण्डवों की ओर से उपस्थित थे और संसार की कोई भी शक्ति अधर्म का पक्ष लेने वालों को विजय नहीं दिला सकती। इसलिए भीष्म पितामह ने अपने नैतिक उत्तरदायित्व का पालन करने और हस्तिनापुर एवं कौरवों के हित की रक्षा हेतु पाण्डवों के विरुद्ध युद्ध करने का निर्णय लिया। यह निर्णय भीष्म पितामह के व्यक्तित्व की गहनता को रेखांकित करता है।",
