        commentary: "துரியோதனனின் தன்னைப் பெருமைப்படுத்திக் கொள்ளும் வார்த்தைகள் ஒரு வீண் தற்புகழ்ச்சி செய்கிற மனிதனின் எடுத்துக்காட்டான வார்த்தைகளாக இருந்தன. தற்பெருமை உடைய மக்கள் முடிவு நெருங்கும் பொழுது, தங்கள் நிலைமையை மதிப்பிடுவதில் தாழ்மையுடன் இருப்பதற்கு பதிலாக மனம் போன போக்கில் வீண் கர்வத்தில் ஈடுபடுகிறார்கள். பீஷ்மரால் பாதுகாக்கப்பட்ட அவர்களின் பலம் வரம்பற்றது என்று துரியோதனன் கூறியது விதியின் இந்த துயரமான முரண்பாட்டை பிரதிபலித்தது.\nகௌரவ ராணுவத்தின் தளபதி மூதாதையர் பீஷ்மர் ஒரு விதிவிலக்கான போர்வீரர் மட்டுமல்லாமல் ஒரு அசாதாரண வரத்தை பெற்றிருந்தவர். இந்த வரத்தினால் அவர் தன் உயிர் துறக்கும் நேரத்தை நிர்ணயிக்கும் உரிமையைப் பெற்று இருந்தார் என்பதால் நடைமுறையில் அவர் வெல்ல முடியாதவராகத் திகழ்ந்தார். பாண்டவ இராணுவம் தனது உறுதியான எதிரியான பீமனால் பாதுகாக்கப்பட்டதை அறிந்த துரியோதனன், தனது பாட்டனார் பீஷ்மரின் பலத்தை பீமனுடன் ஒப்பிடத் துவங்கினான்.\nகுருவம்சத்தின் மிக வயதான உறுப்பினரான பீஷ்மர் தனது பேரக்குழந்தைகள் ஆன கௌரவர் மற்றும் பாண்டவர்களின் நலனில் அக்கறை கொண்டிருந்தார். இந்த புனிதப் போரில், உலகின் அனைத்து பெரிய வீரர்களுடனும், ஒப்புயர்வற்ற ஸ்ரீ கிருஷ்ணரே பாண்டவர்களுடன் இருந்ததால், தர்மம் அவர்கள் பக்கத்தில் இருந்தது என்பதையும், மேலும், முழு பிரபஞ்சத்திலும் எந்த சக்தியாலும் அதர்மம் வெல்ல வைக்க முடியாது என்பதையும், பீஷ்மர் அறிந்திருந்தார். அவர் பாண்டவர்களிடம் இரக்கம் உள்ளவராக இருந்தபோதிலும் ஹஸ்தினாபூர் சிம்மாசனத்தையும் அதன் குடிமக்களையும் குறித்து தனது நெறிமுறை கடமை உணர்ச்சியால் கட்டுப்பட்டார். எனவே, அரைமனதுடன், அவர்களுக்கு எதிராக கௌரவ இராணுவத்தை வழிநடத்தினார். இந்த முடிவு பீஷ்மரின் ஆளுமையின் புதிரான தன்மையை கோடிட்டுக் காட்டுகிறது.",
