        commentary: "भीष्म पितामह अपने पौत्र दुर्योधन के भीतर के भय को समझ गये थे और उसके प्रति अपने स्वाभाविक करुणाभाव के कारण उन्होंने दुर्योधन को प्रसन्न करने के लिए उच्च स्वर में शंखनाद किया। यद्यपि वे जानते थे कि दूसरे पक्ष पाण्डवों की सेना में स्वयं परम पुरुषोत्तम भगवान श्रीकृष्ण के उपस्थित होने पर दुर्योधन किसी भी स्थिति में युद्ध में विजय प्राप्त नहीं कर सकता। फिर भी भीष्म दुर्योधन को यह बताना चाहते थे कि वे युद्ध करने के अपने दायित्व का भली-भांति पालन करेंगे और इस संबंध में किसी भी प्रकार की शिथिलता नहीं दिखाएंगे। उस समय प्रचलित युद्ध के नियमों के अनुसार शंखनाद द्वारा युद्ध का उद्घाटन किया जाता था।",
