        commentary: "इस श्लोक में श्रीकृष्ण के लिए \"हृषीकेश\" शब्द का प्रयोग किया गया है जिसका अर्थ मन और इन्द्रियों का स्वामी है। श्रीकृष्ण स्वयं अपनी और समस्त प्राणियों के मन और इन्द्रियों के परम स्वामी हैं। भगवान श्रीकृष्ण ने धरती पर अपनी अद्भुत लीलाएं करते समय भी अपने मन और इन्द्रियों को पूर्ण नियंत्रण में रखा।।",
