        commentary: "‘ஹ்ருஷிகேஶ்' என்ற சொல்லுக்கு மனம் மற்றும் புலன்களின் இறைவன் என்று பொருள். இது ஸ்ரீ கிருஷ்ணருக்குப் பயன்படுத்தப்பட்டது. அதாவது மனம் மற்றும் புலன்களின் இறைவன். ஸ்ரீ கிருஷ்ணர் எல்லோருடைய மனங்களின் மற்றும் புலன்களின் (அவரது புலன்கள் உட்பட) ஏகாதிபதி. மேலும் அவர் தனது தெய்வீக பொழுதுபோக்குகள் அனைத்திலும் தனது மனதின் மற்றும் புலன்களின் முழுமையான கட்டுப்பாட்டை பிரதிபலித்தார்.",
