        commentary: "युधिष्ठिर पाण्डवों के सबसे बड़े भाई थे। यहाँ उन्हें राजा कहकर संबोधित किया गया है। उन्होंने राजसूय यज्ञ का अनुष्ठान कर 'राजा' कहलाने की उपाधि पायी थी। उनके आचरण में उदारता सदैव परिलक्षित होती थी फिर चाहे जब वह महलों में रहे या अपने निर्वासन काल के दौरान वनों में।\nधृतराष्ट्र को संजय द्वारा 'पृथ्वी का राजा' कहा गया है। देश की रक्षा करना या उसे विनाशकारी युद्धों में उलझाए रखना यह सब राजा के हाथों में होता है। इस प्रकार अप्रत्यक्ष रूप से संजय के इस संबोधन का तात्पर्य यह है-\"सेनाएं युद्ध की ओर बढ़ रही हैं, हे राजा धृतराष्ट्र केवल आप ही उसे वापिस बुला सकते हैं। अतः आपका क्या निर्णय है?\"",
