        commentary: "பாண்டவர்களில் மூத்தவரான யுதிஷ்டிரர் இங்கு மன்னர் என்று அழைக்கப்படுகிறார் ஏனெனில் மன்னர் பட்டத்தை அவர் ராஜஸுய யாகம் என்ற அரச யாகத்தை நடத்தியதால் பெற்றார். இதனால் மற்ற உலக அரசர்கள் அவருக்குக் கப்பம் செலுத்தினர் . மேலும், அவர் வனத்திலோ அரண்மனையிலோ எங்கு வாழ்ந்தாலும் எப்பொழுதும் அரசனுக்குரிய குணவதம் மற்றும் பெருந்தன்மையை பிரதிபலித்தார்.\nத்ருதராஷ்டிரர் ஸஞ்ஜயனால் ‘பூமியின் ஆட்சியாளர்’ என்று அழைக்கப்படுகிறார். ஒரு நாட்டைப் பாதுகாப்பது அல்லது ஒரு நாசகரமான போரில் ஈடுபடுவது எல்லாம் ஆட்சியாளரின் கைகளில் உள்ளது. எனவே பட்டப்பெயரில் மறைந்துள்ள உட்பொருள், ‘படைகள் போரை நோக்கிச் செல்கின்றன. ஓ ஆட்சியாளரே, த்ருதராஷ்டிடிரரே, உங்களால் மட்டுமே அவர்களை திரும்ப அழைக்க முடியும். நீங்கள் என்ன முடிவு எடுக்கப் போகிறீர்கள்?’",
