        commentary: "பாண்டவ இராணுவத்தின் பல்வேறு சங்கு ஓடுகளின் மிகப்பெரிய ஒலி அவரது மகன்களின் இதயங்களை சிதைத்து வருவதாக சஞ்ஜயன் த்ரிதராஷ்டிரருக்கு தெரிவித்தார். இருப்பினும், கௌரவ சேனைகள் தங்கள் சங்குகளை ஊதும் பொழுது பாண்டவர் படையில் அத்தகைய பாதிப்பு எதுவும்குறிப்பிடப்படவில்லை. பாண்டவர்கள் இறைவனிடம் தஞ்சம் புகுந்ததால், அவர்கள் காப்பாற்றப்படுவார்கள் என்ற நம்பிக்கையில் இருந்தனர். மறுபுறம், கௌரவர்கள், தங்கள் சொந்த பலத்தை நம்பி, தங்கள் குற்றங்களின் மனசாட்சியால் குத்தப்பட்டு, தோல்விக்கு பயந்தனர்.",
