        commentary: "శక్తిశాలి అయిన హనుమంతుడు తన రథం (జెండా) మీద ఉన్నాడు కాబట్టి, అర్జునుడికి కపి ధ్వజుడు అన్న పేరు ఉంది. దీనికి ఒక పూర్వ వృత్తాంతం ఉంది.\n\nఒకసారి అర్జునుడు విలు విద్యలో తనకున్న ప్రావీణ్యానికి గర్వపడి, శ్రీ రామచంద్రుని సమయంలో వానరములు భారతదేశం నుండి లంకకు సేతువు (బ్రిడ్జి)ని నిర్మించటానికి ఎందుకు అంత కష్టపడ్డారో తనకు అర్థం కావటంలేదు అని, శ్రీ కృష్ణునితో అన్నాడు. తనే గనక వుంటే, బాణములతో ఒక వారధిని చేసేవాడిని అన్నాడు. శ్రీ కృష్ణుడు, అది ఎలా చేసేవాడో చూపించమన్నాడు. అర్జునుడు తన శర పరంపరతో ఒక వంతెనని నిర్మించాడు. శ్రీ కృష్ణుడు హనుమంతుడిని ఆ వంతెనని పరీక్షించడానికి రమ్మని పిలిచాడు. హనుమ దానిపై నడవటం ప్రారంభించగానే ఆ వంతెన కూలిపోవటం మొదలయింది. తన బాణాలతో చేసిన వారధి రాముని అపారమైన (వానర) సైన్య బరువుని తట్టుకోలేదని అర్జునుడికి అర్థం అయింది మరియు అర్జునుడు తన తప్పుకి క్షమాపణ వేడుకున్నాడు. అప్పుడు హనుమంతుడు అర్జునుడికి, ఎప్పుడూ తన ప్రావీణ్యం చూసుకొని గర్వపడొద్దని హితవు చెప్పాడు. హనుమ దయాళువై, మహాభారత యుద్ధంలో నీ రథంపై కూర్చుంటాను అని అర్జునుడికి వరం ఇచ్చాడు. ఈ విధంగా, అర్జునుడి రథం, హనుమంతుని చిహ్నంతో ఉన్న జెండాని కలిగి వుంది. దీనితో అతనికి 'కపి ధ్వజుడు', అంటే జెండాపై వానరుడు ఉన్నవాడు, అన్న పేరొచ్చింది.",
