        meaning: "அந்த நேரத்தில் தனது தேரின் கொடியில் ஹனுமானின் முத்திரை குறித்த பாண்டுவின் மகன் அர்ஜுனன் தனது வில்லை எடுத்துக் கொண்டார். ஓ அரசரே, உங்கள் மகன்கள் அவருக்கு எதிராக அணிவகுத்து வருவதை பார்த்த அர்ஜூனன் ஸ்ரீ கிருஷ்ணரிடம் பின்வரும் வார்த்தைகளை பேசினார்.",
