        meaning: "అర్జునుడు ఇలా అన్నాడు: ఓ అచ్యుతా (శ్రీకృష్ణా), దయచేసి నా రథాన్ని రెండు సైన్యాల మధ్యకి తీసుకువెళ్ళుము. ఈ మహా పోరాటంలో, రణరంగంలో నిలిచియున్న ఎవరెవరితో యుద్ధం చేయవలసి ఉన్నదో నేను చూడాలి.",
