        commentary: "அர்ஜுனன் முழுப் படைப்பின் அதிபதியான ஸ்ரீ கிருஷ்ணரின் பக்தர். இருப்பினும், இந்த வசனத்தில், அர்ஜுனன் தனது தேரை விரும்பிய இடத்திற்கு ஓட்டுமாறு இறைவனிடம் அறிவுறுத்தினார். இது கடவுளின் பக்தர்களுடன் உள்ள உறவின் இனிமையை வெளிப்படுத்துகிறது. அவர்கள் அவர் மீது கொண்ட பக்தி கடவுளை அடிமைப்படுத்துகிறது அவர்களுக்கு அடிமைப்படுத்துகிறது. அவர்கள் தம்மீது கொண்ட அன்பிற்குக் கடன்பட்டவராக, பகவான் தம் பக்தருக்கு அடியாராகிறார்.\nஅஹம் பக்தபராதீனோ ஹ்யஸ்வதந்த்ர இவ த்விஜ\nஸாதுபிர் கிரஸ்த ஹ்ருதயோ பக்தைர் பக்த-ஜன-ப்ரியஹ\n( பாகவதம் 9.4.63)\n‘நான் மிகவும் சுதந்திரமாக இருந்தாலும், என் பக்தர்களால் நான் அடிமைப்படுகிறேன். அவர்கள் எனக்கு மிகவும் பிரியமானவர்கள், அவர்களுடைய அன்பிற்காக நான் அவர்களுக்கு கடமைப்பட்டிருக்கிறேன்.’ அர்ஜுனனின் பக்திக்கு கட்டுப்பட்டு, ஸ்ரீ கிருஷ்ணர் தேர் ஓட்டும் பதவியை ஏற்று, பயணிகள் இருக்கையில் அமர்ந்திருந்த அர்ஜுனின் வேண்டுகோளை நிறைவேற்றினார்.",
