        meaning: "అక్కడున్న తన బంధువులందరినీ చూసిన కుంతీ పుత్రుడు అర్జునుడు, కారుణ్య భావం ఉప్పొంగినవాడై, తీవ్ర దుఃఖంతో ఈ విధంగా పలికెను.",
