        commentary: "అర్జునుడు తన బంధువులను యుద్ధభూమిలో చూసి, తగినట్లుగా యుద్ధం చేయడం కంటే, వారితో కలిసి ఉండడం అనేది అతని మనస్సును తీవ్రంగా కలచివేసింది. అతని హృదయాన్ని కరుణావశాన్నిడి దుఃఖం కుట్టింది, మరియు ఆత్మీయతవలన అతను పిరికితనం పొందాడు. అతని శౌర్యం అక్కణక పోయి, దుఃఖం అతనిని తీవ్రంగా పట్టుకుంది. దీనివల్ల అతని మృదువైన హృదయాన్ని, అంగీకార భావాన్ని ప్రసారం చేసే విధంగా సంజయుడు అర్జునుడిని 'కుంతీ పుత్రుడిగా' అభివర్ణించాడు, ఇది అతని అసాధారణమైన బంధితత్వాన్ని, కరుణాత్మక స్వభావాన్ని సూచిస్తుంది.",
