        commentary: "பாசம் ஒரு பொருள் உணர்வாகவோ அல்லது ஆன்மீக உணர்வாகவோ இருக்கலாம். ஒருவரின் உறவினர்களுக்கான பற்றுதல் அவர்களின் உடலுடன் அடையாளம் காண்பதில் இருந்து எழுகின்ற உணர்வு. இவ்வாறே, தன்னை உடலாக நினைத்து, தன் உறவினர்களிடம் பற்றுகொள்ளும் இந்த இணைப்பு அறியாமையை அடிப்படையாகக் கொண்டது. மற்றும், ஒருவரை மேலும் பொருள் உணர்வுக்கு இழுக்கிறது. இறுதியில், அத்தகைய இணைப்பு வலியில் முடிகிறது, ஏனெனில் மரணத்தின் போது, குடும்ப உறவுகளும் முடிவடைகின்றன.\nமறுபுறம், ஒப்புயர்வற்ற இறைவன் நம் ஆன்மாவின் தந்தை, தாய், நண்பர், எஜமானர் மற்றும் பிரியமானவர். இதன் விளைவாக, அவருடன் பற்றுதல் என்பது ஒரு ஆன்மீக உணர்வாகும், இது நனவை உயர்த்துகிறது மற்றும் புத்தியை ஒளிரச் செய்கிறது. பெருங்கடல் போன்ற கடவுள் மீதான அன்பு அனைத்தையும் உள்ளடக்கியது அதே சமயம் உடல் உறவுகளுக்கான அன்பு குறுகியது மற்றும் வேறுபட்டது. இங்கே, அர்ஜுனன் பொருள் பற்றுதலை அனுபவித்துக்கொண்டிருந்தான், அது அவனது மனதை ஒரு இருள் கடலில் மூழ்கடித்து, தன் கடமையைச் செய்வதை நினைத்து அவனை நடுங்கச் செய்தது.",
