        commentary: "ஒருவரை கொல்வது என்பது பாவச்செயலாகும். மேலும் ஒருவரின் உறவினர்களைக் கொல்வது இன்னும் மோசமான செயலாக கருதப்படுவதால் அர்ஜுனனின் குழப்பம் மேலோங்கியது. இப்படிப்பட்ட இதயமற்ற செயலில் ஈடுபட்டாலும் அந்த வெற்றி தனக்கு மகிழ்ச்சியைத் தராது என்று அர்ஜுனன் உணர்ந்தார். இந்த வெற்றியை அடைய அவர் கொல்ல வேண்டிய அவரது நண்பர்கள் மற்றும் உறவினர்களுடன் அந்த வெற்றியின் பெருமையை பகிர்ந்து கொள்ள முடியாது.\nஇங்கே, அர்ஜுனன் தனது தாழ்ந்த உணர்வுகளை உன்னதமான உணர்வுகளோடு ஒப்பிட்டு குழப்பம் அடைகிறார். உலக உடைமைகள் மற்றும் பொருள் சேமிப்பு பற்றிய அலட்சியமான போக்கு போற்றத்தக்க ஆன்மீக நற்பண்பு. ஆனால், அர்ஜுனன் ஆன்மீக உணர்வுகளை அனுபவிக்க வில்லை. மாறாக அவரது மாயை போலித்தனமான இரக்க வார்த்தைகளாக மாறிவிட்டது. நல்லொழுக்க உணர்வுகள் உள் நல்லிணக்கத்தையும், திருப்தியையும், ஆன்மாவின் மகிழ்ச்சியையும் தருகின்றன. அர்ஜுனனின் இரக்க உணர்வானது ஆழ்நிலை உணர்வை அடிப்படையாகக் கொள்ளவில்லை. அவரது இரக்கம் ஆழ்நிலை உணர்வை அடிப்படையாகக் கொண்டிருந்தால் அந்த உணர்வால் அவர் உயர்த்தப்பட்டு இருப்பார். ஆனால் அவரது அனுபவம் முற்றிலும் நேர்மாறானது--எனவே, கையில் இருக்கும் பணியில் அதிருப்தி மற்றும் ஆழ்ந்த மகிழ்ச்சி அற்று அவர் தனது மனதிலும் புத்தியிலும் முரண்பாட்டை உணர்கிறார். அவரது உணர்வின் விளைவு, அவரின் இரக்கம் மாயையிலிருந்து உருவானது என்பதைக் குறிக்கிறது.",
