        commentary: "துரோணாச்சாரியரும், கிருபாச்சாரியரும் அர்ஜுனின் ஆசிரியர்கள்; பீஷ்மரும் சோமதத்தரும் அவருடைய மாமாக்கள்; பூரிஷ்ரவரும் (சோமதத்தரின் மகன்) ஆகியோர் அவருடைய தந்தையைப் போன்றவர்கள்; புருஜிதன், குந்திபோஜன், ஶ்ல்யன் மற்றும் சகுனி ஆகியோர் அவரது தாய்வழி மாமன்கள்; த்ருதராஷ்டிரரின் நூறு மகன்கள் அவரது ஒன்றுவிட்ட சகோதரர்கள்; லக்ஷ்மணன் (துரியோதனனின் மகன்) அவருடய குழந்தையைப் போன்றவன். அர்ஜுனன் போர்க்களத்தில் இருக்கும் தனது பல்வேறு உறவினர்களைக் குறிப்பிடுகிறார். ‘இருந்தாலும்’ என்று பொருள்படும் அபி என்ற வார்த்தையை அவர் இருமுறை பயன்படுத்துகிறார். முதலாவதாக, ‘நான் அவர்களுடைய உறவினனாகவும், நலன் விரும்பியாகவும் இருந்தாலும், அவர்கள் ஏன் என்னைக் கொல்ல விரும்புகிறார்கள்?’ இரண்டாவதாக, ‘அவர்கள் என்னைக் கொல்ல ஆசைப்பட்டாலும், நான் ஏன் அவர்களைக் கொல்ல வேண்டும்?’",
