        commentary: "முந்தைய வசனத்தில், ‘இருந்தாலும்’ என்று இரண்டு முறை சொல்லிவிட்டு, தன் உறவினர்களைக் கொல்லக்கூடாது என்ற தன் நோக்கத்தை நியாயப்படுத்த, அர்ஜுனன் மீண்டும் சொல்கிறார். ‘நான் அவர்களைக் கொன்றாலும், அப்படிப்பட்ட வெற்றியால் நான் என்ன மகிழ்ச்சி அடைவேன்?’\nபெரும்பாலான சூழ்நிலைகளில், சண்டையிடுவதும் கொல்வதும் ஒரு தெய்வபக்தியற்ற செயலாகும். இது மன வருத்தம் மற்றும் குற்ற உணர்வுகளை உருவாக்குகிறது. அஹிம்ஸை ஒரு பெரிய தர்மம் எ.ன்று வேதங்கள் கூறுகின்றன. தீவிர நிகழ்வுகளைத் தவிர, வன்முறை ஒரு பாவம்: மா ஹின்ஸ்யாத்ஸர்வ பூதானி '’எந்த உயிரையும் கொல்லாதே’. இங்கே, அர்ஜுன் தனது உறவினர்களைக் கொல்ல விரும்பவில்லை. ஏனென்றால் அவர் அதை பாவம் என்று கருதுகிறார். இருப்பினும், வஸிஷ்ட ஸ்மிருதி (வசனம் 3.19) பின்வரும் ஆறு வகையான ஆக்கிரமிப்பாளர்களுக்கு எதிராக நம்மைத் தற்காத்துக் கொள்ள நமக்கு உரிமை உண்டு என்று கூறுகிறது: ஒருவரின் சொத்துக்களுக்கு தீ வைப்பவர்கள், ஒருவரின் உணவை விஷமாக்குபவர்கள், கொலை செய்ய முற்படுபவர்கள், மற்றவரது செல்வத்தை திருடுபவர்கள், ஒருவரது மனைவியைக் கடத்த வருபவர்கள், ஒருவருடைய ராஜ்யத்தை அபகரிப்பவர்கள். மனு ஸ்மிருதி (8.351) தற்காப்புக்காக அத்தகைய ஆக்கிரமிப்பாளரைக் கொன்றால் அது பாவமாக கருதப்படாது என்று கூறுகிறது.",
