        meaning: "यद्यपि लोभ से अभिभूत होने के कारण वे अपने स्वजनों के विनाश और अपने मित्रों के साथ विश्वासघात करने में कोई दोष नहीं देखते हैं। तथापि हे जनार्दन! जब हमें स्पष्टतः अपने बंधु बान्धवों का वध करने में अपराध दिखाई देता है तब हम ऐसे पापमय कर्म से क्यों न दूर रहें?",
