        commentary: "पुरातन परम्पराओं और प्रथाओं के अनुसार कुल के वयोवृद्ध लोग उच्च मूल्यों और आदर्शों को अगली पीढ़ी के कल्याण हेतु उन्हें हस्तांतरित करते हैं। ये महान परम्पराएं कुल के सदस्यों को मानवीय मूल्यों और धार्मिक मर्यादाओं का पालन करवाने में सहायता करती हैं। यदि कुल के वयोवृद्धों की समय से पूर्व मृत्यु हो जाती है तब भावी पीढ़ियां कुल के उनके मार्गदर्शन और शिक्षण से वंचित हो जाती हैं। अर्जुन के कहने का तात्पर्य यह है कि जब कुलों का विनाश हो जाता है तब उसकी महान परम्पराएं भी उसके साथ समाप्त हो जाती हैं और कुल के शेष सदस्यों में अधर्म और व्यभिचार की प्रवृत्ति बढ़ती है जिससे वे अपनी आध्यात्मिक उन्नति का अवसर खो देते हैं। इसलिए अर्जुन के अनुसार कुल के आदरणीय वयोवृद्ध सदस्यों को कभी भी नहीं मारना चाहिए।",
