        commentary: "వైదిక నాగరికతలో స్త్రీలకు ఉన్నతమైన స్థానమిచ్చి, వారిని పవిత్రంగా ఉండాలని సూచించబడింది. మను-స్మృతిలో కూడా ‘యత్ర నార్యస్ తు పూజ్యంతే రమంతే తత్ర దేవతాః’ అనే వాక్యం ఉంది, అంటే ఎక్కడ స్త్రీలు పవిత్రంగా ఉంటారో, అక్కడ దేవతలు ఆనందిస్తారు. కానీ, స్త్రీలు అధర్మపరమైన ప్రవర్తనతో ఉంటే, అప్పుడు అవాంఛిత సంతానం జన్మిస్తారు. బాధ్యతారహితమైన పురుషులు వారి జారత్వం వల్ల స్త్రీలను తప్పుదారి పట్టించి, ఈ అవాంఛిత సంతానాన్ని జన్మించిస్తారు.",
