        commentary: "वैदिक सभ्यता में समाज में स्त्रियों को उच्च स्थान प्राप्त था और स्त्रियों में शुचिता एवं सदाचारिता के गुणों की आवश्यकता को अत्यन्त महत्त्व दिया जाता था। इसलिए मनु स्मृति में वर्णन किया गया है:\n'यत्र नार्यस्तु पूज्यन्ते रमन्ते तत्र देवताः'\nअर्थात (3:56) \"जहाँ स्त्रियाँ पतिव्रता, संयत और सदाचारी जीवन व्यतीत करती हैं वहाँ वे अपनी पवित्रता के लिए पूरे समाज द्वारा पूजी जाती हैं और वहाँ स्वर्ग के देवता भी हर्षित होते हैं।\" जब स्त्रियाँ पतिता बन जाती हैं तब अनुत्तरदायी पुरुष इसका लाभ उठा कर पर स्त्री गमन के कुमार्ग में प्रवृत्त हो जाते हैं और जिसके परिणामस्वरूप अवांछित सन्तानें जन्म लेती हैं।",
