        meaning: "अपने दुष्कर्मों से कुल परम्परा का विनाश करने वाले दुराचारियों के कारण समाज में अवांछित सन्तानों की वृद्धि होती है और विविध प्रकार की सामुदायिक और कुटुंब तथा पारिवारिक कल्याण की गतिविधियों का भी विनाश हो जाता है।",
