        commentary: "सनातन-धर्म या वर्णाश्रम द्वारा निर्धारित चारों वर्गों के लिए सामुदायिक योजनाएं इसलिए नियोजित हैं कि मनुष्य मोक्ष प्राप्त कर सके। अतः समाज के निकृष्ट जनों द्वारा सनातन परम्परा के विखण्डन से उस समाज में अव्यवस्था फैलती है, फलस्वरूप लोग जीवन के उद्देश्य भगवत्प्राप्ति को भूल जाते हैं। ऐसे नायक अंधे कहलाते हैं और जो लोग इनका अनुगमन करते हैं वे निश्चय ही कुव्यवस्था की ओर अग्रसर होते हैं।",
