        commentary: "अर्जुन अपने तर्कों को अपने निजी अनुभव तथा आचार्यों से जो सुन रखा है उस के आधार पर प्रस्तुत करता है। वास्तविक ज्ञान प्राप्त करने की यही विधि है जिस व्यक्ति ने पहले से ज्ञान प्राप्त कर रखा है उस व्यक्ति की सहायता के बिना कोई भी वास्तविक ज्ञान तक नहीं पहुँच सकता। वर्णाश्रम-धर्म की एक पद्धति के अनुसार मृत्यु के पूर्व मनुष्य को पापकर्मों के लिए प्रायश्चित करना होता है जो पापात्मा है उसे इस विधि का अवश्य उपयोग करना चाहिए।",
