        commentary: "வரவிருக்கும் போரில் இருந்து வரும் பல தீமைகளை அர்ஜுன் குறிப்பிட்டார். ஆனால், இந்த தீயவர்களை சமூகத்தில் மேலோங்க அனுமதித்தால் உண்மையில் தீமைகள் மேலோங்கும் என்பதை அவரால் பார்க்க முடியவில்லை. ஆச்சரியத்தை வெளிப்படுத்த அஹோ என்ற வார்த்தையைப் அவர் பயன்படுத்துகிறார். பத என்ற வார்த்தைக்கு, ‘பயங்கரமான முடிவு’ என்று அர்த்தம்.‘இந்தப் போரின் பயங்கரமான விளைவுகள் நமக்கு தெரிந்தாலும், நாம் பாவம் செய்ய முடிவு செய்திருப்பது எவ்வளவு ஆச்சரியம்’ என்று அர்ஜுன் சொல்கிறார்.\nபல முறை, மக்கள் தங்கள் சொந்த தவறுகளைப் பார்க்க தவறி, அவர்களின் தவறுகளுக்காக சூழ்நிலைகள் மற்றும் பிறரை காரணம் காட்டுகிறார்கள். அதேபோல், திருதராஷ்டிரரின் மகன்கள் பேராசையால் தூண்டப்பட்டதாக அர்ஜுன் உணர்ந்தார்; அவரது இரக்கத்தின் வெளிப்பாடானது ஒரு ஆழ்நிலை உணர்வு அல்லாமல், உடல் என்ற அறியாமையின் அடிப்படையில் உருவான பொருள் மாயையின் மோகம் என்பதை அவரால் உணர முடியவில்லை. அர்ஜுனனின் அனைத்து வாதங்களிலும் உள்ள சிக்கல் என்னவென்றால், அதை அவர் அவரது உடல் ரீதியான பற்றுதல், இதய பலவீனம், மற்றும் தனது கடமையில் இருந்து தவறியதை நியாயப்படுத்த பயன்படுத்தினார். அர்ஜுனின் வாதங்கள் ஏன் ஏற்றுக்கொள்ள முடியாதவை என்பதற்கான காரணங்களை ஸ்ரீ கிருஷ்ணர் அடுத்து வரும் அத்தியாயங்களில் விளக்குகிறார்.",
